/// A built-in sound a sentence row can play instead of TTS (`soundKey`).
class BuiltInSound {
  const BuiltInSound({required this.asset, this.loops = false});

  /// Asset path relative to `assets/` (the form audioplayers' `AssetSource`
  /// takes). Generated by `tool/make_sounds.py`.
  final String asset;

  /// Loops until stopped (or [alarmLoopLimit]); a property of the sound, not
  /// of the row.
  final bool loops;
}

const builtInSounds = {
  'siren': BuiltInSound(asset: 'sounds/siren.wav', loops: true),
  'bell': BuiltInSound(asset: 'sounds/bell.wav'),
  'horn': BuiltInSound(asset: 'sounds/horn.wav'),
};

/// A looping alarm stops by itself after this long (safety net).
const alarmLoopLimit = Duration(minutes: 2);
